(function(E){ const x = E["int-m1"] = E["int-m1"] || {units:{}}; x.units["int-cp-1"] = {"exit":{"id":"c-int-cp-1-x","course":"interview","unit":"int-cp-1","type":"exit","items":[{"from":"int-1","kind":"blank","prompt":"I ___ my first job in sales ten years ago.","options":["have got","got","get"],"correct":1,"point":2,"why":{"en":"got: 'ten years ago' is a finished time, so use the past simple. 'Have got' can't go with ago, and 'get' is the present.","tr":"got: 'ten years ago' bitmiş bir zamandır, bu yüzden past simple. 'Have got' ago ile kullanılmaz; 'get' geniş zamandır.","fa":"got درست است، چون ten years ago زمان تمام‌شده است و گذشته‌ی ساده می‌خواهد. have got با ago نمی‌آید و get زمان حال است."}},{"from":"int-10","kind":"mcq","prompt":"Which CV line is written correctly?","options":["Raised sales by 20% in one year.","Raised sales by %20 in one year.","Raised sales %20 in one year."],"correct":0,"point":2,"why":{"en":"'Raised sales by 20%': in English the percent sign comes after the number, and 'by' gives the size of the change. '%20' is the Turkish way of writing it.","tr":"'Raised sales by 20%': İngilizcede yüzde işareti sayıdan sonra gelir; 'by' değişimin miktarını verir. '%20' Türkçedeki yazılışıdır.","fa":"«Raised sales by 20%» درست است، چون در انگلیسی علامت درصد بعد از عدد می‌آید و by مقدار تغییر را می‌گوید. %20 شیوه‌ی نوشتن ترکی است."}},{"from":"int-1","kind":"mcq","prompt":"Which fact belongs in your introduction for a customer support job?","options":["I have answered about 40 customer emails a day for three years.","I grew up in a big family in a small town near the sea.","I like travelling and music, and I play the guitar at weekends."],"correct":0,"point":1,"why":{"en":"Answering 40 customer emails a day matches a customer support job, with a number. A big family and guitar at weekends say nothing about the job.","tr":"Günde 40 müşteri e-postası cevaplamak, bir sayıyla, müşteri destek işine uyar. Kalabalık aile ve hafta sonu gitar işle ilgili bir şey söylemez.","fa":"جواب دادن به ۴۰ ایمیل مشتری در روز، همراه با عدد، به کار پشتیبانی مشتری می‌خورد. خانواده‌ی بزرگ و گیتار آخر هفته چیزی درباره‌ی کار نمی‌گویند."}},{"from":"int-2","kind":"blank","prompt":"\"Do you have a work permit?\" \"Yes, I ___. It runs until 2029.\"","options":["does","am","do"],"correct":2,"point":2,"why":{"en":"do: 'Do you have...?' is answered with do. 'Does' is for he or she, and 'am' answers a be question.","tr":"do: 'Do you have...?' sorusu do ile cevaplanır. 'Does' he ya da she içindir; 'am' be sorusuna cevaptır.","fa":"do درست است، چون جواب کوتاه Do you have با do است. does برای he و she است و am جواب سؤال be است."}},{"from":"int-2","kind":"mcq","prompt":"The recruiter says your interview is on \"the 13th\". What should you do?","options":["Say \"okay\" and hope you heard it right","Say it back: \"So that's Tuesday the 13th?\"","Ask them to send you a letter about it by post"],"correct":1,"point":1,"why":{"en":"Say it back: 'So that's Tuesday the 13th?' A wrong date is easy to miss on the phone. Hoping or asking for a letter wastes time.","tr":"Tekrar et: 'So that's Tuesday the 13th?' Telefonda yanlış tarihi kaçırmak kolaydır. Umut etmek ya da mektup istemek zaman kaybettirir.","fa":"تکرارش کن: «So that's Tuesday the 13th?» پشت تلفن اشتباه شنیدن تاریخ آسان است. امیدوار ماندن یا خواستن نامه وقت را هدر می‌دهد."}},{"from":"int-2","kind":"mcq","prompt":"What is the best way to answer a salary question?","options":["Give a range you have checked, then ask for theirs.","Say you will take anything they offer, because you need work.","Tell them about your rent and bills, so they understand."],"correct":0,"point":1,"why":{"en":"Give a range you have checked, then ask for theirs: it is honest and leaves room. 'Anything you offer' and your bills weaken your position.","tr":"Araştırdığın bir aralık ver, sonra onlarınkini sor: dürüsttür ve pay bırakır. 'Ne verirseniz' demek ve faturalarını anlatmak pozisyonunu zayıflatır.","fa":"بازه‌ای را بگو که بررسی کرده‌ای و بعد بازه‌ی آن‌ها را بپرس؛ صادقانه است و جا برای مذاکره می‌گذارد. «هر چه بدهید» و حرف از قبض‌ها موقعیتت را ضعیف می‌کند."}},{"from":"int-3","kind":"blank","prompt":"I find this kind of work really ___.","options":["interested","interesting","interest"],"correct":1,"point":2,"why":{"en":"interesting: -ing describes the work that causes the feeling. 'Interested' is how a person feels, and 'interest' is a noun or a verb.","tr":"interesting: -ing duyguya sebep olan işi anlatır. 'Interested' kişinin ne hissettiğidir; 'interest' isim ya da fiildir.","fa":"interesting درست است، چون ‎-ing خود کار را توصیف می‌کند که آن حس را می‌سازد. interested حس آدم است و interest اسم یا فعل است."}},{"from":"int-3","kind":"mcq","prompt":"Which is good small talk before an interview?","options":["Who did you vote for in the last election, if I may ask?","Yes, thanks, the journey was easy. Have you worked here long?","How much do people earn here, and is the pay good?"],"correct":1,"point":3,"why":{"en":"'Yes, thanks, the journey was easy. Have you worked here long?' is safe and friendly. Politics and pay are topics to avoid before an interview.","tr":"'Yes, thanks, the journey was easy. Have you worked here long?' güvenli ve samimidir. Siyaset ve maaş, mülakattan önce kaçınılması gereken konulardır.","fa":"«Yes, thanks, the journey was easy. Have you worked here long?» امن و دوستانه است. سیاست و حقوق موضوع‌هایی‌اند که قبل از مصاحبه باید از آن‌ها دوری کرد."}}]},"writing":{"id":"c-int-cp-1-w","title":{"en":"Your introduction for a new job ad","tr":"Yeni bir ilan için tanıtımın","fa":"معرفی تو برای یک آگهی تازه"},"course":"interview","unit":"int-cp-1","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-1","prompt":{"en":"Change your introduction for this job ad, or for a real ad you like (70-100 words): Customer Support Specialist at an online travel company. Needs: two or more years with customers, good written English, shift work including weekends. The company now sells trips in six new countries. Use the ad's own words for at least two of its requirements.","tr":"Tanıtımını bu iş ilanı ya da beğendiğin gerçek bir ilan için değiştir (70-100 kelime): Çevrimiçi bir seyahat şirketinde Customer Support Specialist. İstenenler: müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonlarını da kapsayan vardiyalı çalışma. Şirket artık altı yeni ülkede seyahat satıyor. En az iki şart için ilanın kendi kelimelerini kullan.","fa":"معرفی‌ات را برای این آگهی یا یک آگهی واقعی که دوست داری تغییر بده (۷۰ تا ۱۰۰ کلمه): Customer Support Specialist در یک شرکت سفر اینترنتی. شرط‌ها: دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، کار شیفتی شامل آخر هفته‌ها. این شرکت حالا در شش کشور تازه سفر می‌فروشد. برای دست‌کم دو شرط از کلمه‌های خود آگهی استفاده کن."},"model":"I currently work as a receptionist at a hotel in Izmir. I have helped guests from more than twenty countries for four years, and I answer about thirty emails in English every day. I work shifts, including weekends. I am applying because your team supports travellers, and I know what people need when a trip goes wrong. I want to solve those problems by phone and by email, every day.","frame":"I currently work as ___ at ___. I have ___ for ___, and I ___. I work ___. I am applying because your team ___, and I ___.","words":[{"word":"currently"},{"word":"shifts"},{"word":"applying"}],"minWords":70,"minSentences":5,"rubric":["Task done: now, before and why, changed for this ad","Organised: now first, then what matches the ad, then why","Language: past simple with a finished time; have + past participle with for or since","Tone: confident and simple, with the ad's own words"],"rubricI18n":{"tr":["Görev: bu ilana göre değiştirilmiş şimdi, önce ve neden","Düzen: önce şimdi, sonra ilana uyanlar, sonra neden","Dil: bitmiş zamanla past simple; for ya da since ile have + üçüncü hâl","Üslup: kendinden emin ve sade, ilanın kendi kelimeleriyle"],"fa":["کامل بودن کار: الان، قبلاً و چرا، متناسب با این آگهی","نظم: اول الان، بعد چیزهای مرتبط با آگهی، بعد چرا","زبان: گذشته‌ی ساده با زمان تمام‌شده؛ have و اسم مفعول با for یا since","لحن: مطمئن و ساده، با کلمه‌های خود آگهی"]},"parts":[{"t":{"en":"Now: what you do today","tr":"Şimdi: bugün ne iş yaptığın","fa":"الان: امروز چه کاری می‌کنی"},"find":["i currently work","currently","i work as","i'm a","i am a"],"sample":"receptionist at a hotel in Izmir"},{"t":{"en":"Before: what matches this ad","tr":"Önce: bu ilana uyanlar","fa":"قبلاً: چیزهایی که با این آگهی جورند"},"find":["i have","i've","since"],"sample":"4 years with guests from 20+ countries · 30 emails a day in English"},{"t":{"en":"The ad's own words for two needs","tr":"İki şart için ilanın kendi kelimeleri","fa":"کلمه‌های خود آگهی برای دو شرط"},"find":["shifts","shift work","weekends","weekend","written english","with customers","travellers"],"sample":"I work shifts, including weekends"},{"t":{"en":"Why this job","tr":"Neden bu iş","fa":"چرا این کار"},"find":["i am applying","i'm applying","applying because","i want to","your team"],"sample":"your team supports travellers; I know what they need"}]},"speaking":{"id":"int-cp-1","course":"interview","unit":"int-cp-1","topic":{"en":"A screening call with no notes","tr":"Notsuz ön eleme görüşmesi","fa":"مصاحبه‌ی تلفنی بدون یادداشت"},"warmup":{"en":"Read the job ad once more. Put your notes away.","tr":"İş ilanını bir kez daha oku. Notlarını kaldır.","fa":"آگهی شغلی را یک بار دیگر بخوان. یادداشت‌هایت را کنار بگذار."},"questions":[{"en":"\"So, tell me about yourself.\"","tr":"\"So, tell me about yourself.\"","fa":"«So, tell me about yourself.»"},{"en":"\"What notice period do you have?\"","tr":"\"What notice period do you have?\"","fa":"«What notice period do you have?»"},{"en":"\"Are you able to work weekends?\"","tr":"\"Are you able to work weekends?\"","fa":"«Are you able to work weekends?»"},{"en":"\"Why do you want to work here?\"","tr":"\"Why do you want to work here?\"","fa":"«Why do you want to work here?»"}],"followups":[{"en":"Answer all four in 90 seconds, then 60, then 45. Short answer, one detail, stop.","tr":"Dördünü de önce 90, sonra 60, sonra 45 saniyede cevapla. Kısa cevap, bir ayrıntı, dur.","fa":"به هر چهار سؤال اول در ۹۰، بعد در ۶۰ و بعد در ۴۵ ثانیه جواب بده. جواب کوتاه، یک نکته، تمام."}],"expressions":[{"phrase":"I currently work as...","meaning":{"en":"Opens your introduction.","tr":"Tanıtımını başlatır.","fa":"معرفی‌ات را شروع می‌کند."}},{"phrase":"So I could start on...","meaning":{"en":"Turns your notice period into a date.","tr":"İhbar süreni bir tarihe çevirir.","fa":"مدت پیش‌آگهی‌ات را به یک تاریخ تبدیل می‌کند."}},{"phrase":"I read that...","meaning":{"en":"Opens your fact about the company.","tr":"Şirketle ilgili bilgini söylemeye başlar.","fa":"حرفت را با واقعیتی درباره‌ی شرکت شروع می‌کند."}}],"model":"I currently work as a hotel receptionist, and I have helped international guests for four years. Sorry, what do you mean by notice period? Thank you. It's four weeks, so I could start on 1 March. Yes, I am able to work weekends. I do that now. I read that you now sell trips in six new countries, and I have helped guests from many countries, so I could help from day one.","selfCheck":[{"en":"My introduction used words from this ad.","tr":"Tanıtımımda bu ilanın kelimelerini kullandım.","fa":"در معرفی‌ام از کلمه‌های همین آگهی استفاده کردم."},{"en":"I gave my notice period and a real date.","tr":"İhbar süremi ve gerçek bir tarih verdim.","fa":"مدت پیش‌آگهی‌ام و یک تاریخ واقعی را گفتم."},{"en":"My short answers used the helper verb.","tr":"Kısa cevaplarımda yardımcı fiil kullandım.","fa":"در جواب‌های کوتاهم فعل کمکی به کار بردم."},{"en":"My \"Why us?\" had a real fact in it.","tr":"\"Neden biz?\" cevabımda gerçek bir bilgi vardı.","fa":"در جواب «چرا ما؟» یک واقعیت گفتم."}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
